		Biz.flag = 'Y';
		Biz.urlMatch = '';

		// 서식목록 조회
		Biz.doSearch = function(pageIdx){

			/*넘어온 화면이 M || P 인지 전역으로 확인*/
			var tmpUrl = window.location.href;
			var tmpMatch = tmpUrl.match(/001(M|P)/);
			Biz.urlMatch = tmpMatch[1];

			var actionId = 'ASIAFE001MR01';
			var params = Page.getParameter();

			if(Biz.flag == 'Y' && params.ntstBscId != null ){		// 법령상세에서 넘어왔을때 USISTA002
				$('ul.select_list li#'+params.ntstBscId).click();
			}else if(Biz.flag == 'Y' && (params.searchNtstBscId != null || params.searchFrmlNm != null)){	// 빠른찾기에서 INDEX
				$('ul.select_list li#'+params.ntstBscId).click();
				$('#searchFrmlNm').val(params.searchFrmlNm);
			}else{		// 재조회시 주소 파라미터 제거
				var url = window.location.href;		
				var cleanUrl = url.split('?')[0];		
				window.history.replaceState({}, document.title, cleanUrl);
			}

			var paramData = $('#searchForm').getData(); 
			if(pageIdx) { 
                paramData['pageIndex'] = pageIdx; 
                paramData['recordCountPerPage'] = Biz.paramCountPerPage;
                $("#select_01").val(Biz.paramCountPerPage);
            } else {
                if($("#select_01").val() > 0) { paramData['recordCountPerPage'] = $("#select_01").val(); }
                Biz.paramCountPerPage = $("#select_01").val();
            }

			if(Biz.paramCountPerPage==0){
				Biz.paramCountPerPage = $("#select_01").val();
			}
			paramData['recordCountPerPage'] = Biz.paramCountPerPage;

			var searchDeffer = Req.doAction(actionId, paramData);	
			searchDeffer.done(function(data){
				var d = data[actionId];
				var list = d.allFrmlDVOList;
				var listNum = (d.recordCount - (d.pageIndex -1) * d.recordCountPerPage);	

				Biz.allFrmlTable.setData(list, { 
					cellTemplate : {
						frmlNm : function(cellValue, rowValue){	
							return $('<a href="javascript:;" class="ov_hidden" title="새창열림">' + cellValue + '</a>');
						} 
						,ntstBscId : function(cellValue, rowValue){
							return listNum--;
						}
						,ntar : function(cellValue, rowValue){
							var result = "서식";
							if(cellValue == 'at') {
								result = "별표 서식"
							}else if(cellValue == 'sttt') {
								result = "법령 서식"
							}else if(cellValue == 'inns'){
								result = "훈령 서식"
							}
							return result
						}
						,ntstPmgDt : function(cellValue, rowValue){
							return Util.formatDocumentDate(cellValue)
						}

					}
				});
				Biz.allFrmlTable.onRowClick(function(rowData){	
   					// 별표, 법령서식일때
   					if(rowData.ntar == 'at' || rowData.ntar == 'sttt'){
   						Page.openPopup("/af/USEAFA002P.do", {
   	                        title : "서식상세",
   	                        width : "1200px",
   	                        height : "970px",
   	                        scrollbars : "yes",
   	                        param : {"ntstBscId" 	: rowData.ntstBscId		// 국세법령기본ID
								   , "ntstBrkdId"	: rowData.ntstBrkdId 	// 국세법령내역ID
								   , "ntstAtFrmlSn" : rowData.ntstAtFrmlSn	// 국세법령별표서식일련번호
								   ,"frmlClsf" : '100000000000000220'					// 메뉴종류
   								   }
   	                    });
   					}else if(rowData.ntar == 'inns'){
   						Page.openPopup("/af/USEAFA002P.do", {
   	                        title : "서식상세",
   	                        width : "1200px",
   	                        height : "970px",
   	                        scrollbars : "yes",
   	                        param : {"ntarBscId" 	: rowData.ntarBscId		// 국세행정규칙기본ID
								   , "ntarBrkdId"	: rowData.ntarBrkdId	// 국세행정규칙내역ID
								   , "ntarFrmlNo"	: rowData.ntarFrmlNo	// 국세행정규칙서식일련번호
								   ,"ntstAtFrmlClCd": rowData.ntstAtFrmlClCd
								   ,"frmlClsf" : '100000000000000220'					// 메뉴종류
   								   }
   	                    });
   					}
				});
				Biz.paging.setPaging(data, {
					search : Biz.doSearch
					,countMsg : $(".bd_info")
				});
				Biz.flag = 'N';
			});
		};

		$('#btn_search').click(function(event){
			Biz.doSearch();
		});

    	$("#select_01").setRecordCountPerPageOptions([10, 20, 30, 50, 100], 100);

		$('#btn_page_search').on('click', function(){
			Biz.paramCountPerPage = $("#select_01").val();
			Biz.doSearch();
		});

		Biz.doSearch();

		$("#searchFrmlNm").onEnterSearch();
	});

