	if(6 < currentScrnId.length){
		$("[data-gnb-scrn-id]").removeClass("active");
		$("[data-submenu-scrn-id]").removeClass("active");
		$(".mo_menu_wrap .depth1_all a.1dep_title").removeClass("on");

