		$(".mo_menu_wrap .depth1_all[data-sitemap-gnb-scrn-id^='" + activeScrnPrefixId + "'] a.1dep_title").addClass("on");
		$(".mo_menu_wrap .depth1_all[data-sitemap-gnb-scrn-id^='" + activeScrnPrefixId + "'] ul.depth2_all").addClass("on");
		$("[data-submenu-scrn-id^='" + activeScrnPrefixId + "']").each(function(){
			if(location.search.indexOf($(this).attr('data-scrnurlprmtcntn')) !== -1){
				$(this).addClass("active");	
			}
		});
	}
}

Biz.setPageSize = function(){
	var ieBool = Util.checkIeBrower();
	if(ClientStorage.has('ntlisPageSize') && ClientStorage.get('ntlisPageSize') != ''){
		var localPageSize = ClientStorage.get('ntlisPageSize');
		var $obj = $('[data-size="'+localPageSize+'"]');
		$obj.siblings().removeClass('active');
		$obj.addClass('active');
		if(localPageSize){
			percent = localPageSize + "%";
			if(ieBool){
				document.body.style.zoom = percent;
			}else{
				$('[data-zoom-area]').each(function(){
					$(this).css("zoom", percent);
				})
			}
		}
	}
}
Biz.setPageSize();
/* 화면 축소 및 확대 버튼 클릭 */
$(".ft_size").find(".lv1,.lv2").click(function(){
	/* 사용자 브라우저 IE인지 체크 */
	var ieBool = Util.checkIeBrower();
	var $active = $();
	$(".ft_size").find('button').each(function(){
		if($(this).hasClass('active')){
			$active = $(this);
		}
		$(this).removeClass('active');
	})
	var percent = "";
	var size = "";
	/* 화면 축소 버튼 */
	if($(this).hasClass("lv1")){
		size = $active.prev().attr('data-size');
		if(size){
			percent = size + "%";
			if(ieBool){
				document.body.style.zoom = percent;
			}else{
				$('[data-zoom-area]').each(function(){
					$(this).css("zoom", percent);
				})
			}
			$active.prev().addClass('active');
		}else{
			$active.addClass('active');
		}
	}else{
		size = $active.next().attr('data-size');
		if(size){
			percent = size + "%";
			if(ieBool){
				document.body.style.zoom = percent;
			}else{
				$('[data-zoom-area]').each(function(){
					$(this).css("zoom", percent);
				})
			}
			$active.next().addClass('active');
		}else{
			$active.addClass('active');
		}
	}
	Biz.setLocalPageSize(size);
	$('.ft_size').find('button.active').attr('title','선택됨')
	$('.ft_size').find('button.active').siblings().attr('title','')
})
$('[data-size]').each(function(){
	var ieBool = Util.checkIeBrower();
	$(this).click(function(){
		$('[data-size]').each(function(){
			$(this).removeClass('active');
		})
		$(this).addClass('active');
		var size = $(this).attr('data-size');
		var percent = size + "%";
		if(ieBool){
			document.body.style.zoom = percent;
		}else{
			$('[data-zoom-area]').each(function(){
				$(this).css("zoom", percent);
			})
		}
		Biz.setLocalPageSize(size);
		$('.ft_size').find('button.active').attr('title','선택됨')
		$('.ft_size').find('button.active').siblings().attr('title','')
	})
})

Biz.setLocalPageSize = function(size){
