		return;
	}
	var dataList = Object.keys(data).slice(0, 10)
	$('#rctSchUl').find('li').remove();
	for(var i in dataList){
		if(data[i].sch){
			var $li = $('<li>');
			var $a = $('<a>').attr('href', 'javascript:;').text(data[i].sch);
			var $btn = $('<button>').attr('type', 'button').addClass('recent_srh_close').append($('<span>').addClass('hide').text('닫기'));
			$li.append($a, $btn)
			$('#rctSchUl').append($li);
		}
	}


	$('#rctSchUl').find('a').click(function(){
		Page.move('/is/USEISA001M.do', {
			'schVcb' : $(this).text()
			,'searchType' : Biz.searchType
		})
