Biz.removeSubRctSch = function(schData){
	var data = ClientStorage.get('ntlisSearch');
	var setSchList = {}
	var subList = [];
	for(var i in data){
		if(data[i].sch != schData){
			subList.push(data[i]);
		}
	}

	for(var i in subList){
		setSchList[i] = subList[i];
	}

	ClientStorage.set('ntlisSearch', setSchList);
	Biz.setSubRctSch();
}

