Biz.getDataWithQuickFindByMobile = function($btn){
	var quickType = $btn.attr('data-quick-find-button');
	var param = $btn.closest("[data-quick-find-area]").getData();
	/* radio name 중복을 피하기 위해 판례 radio의 name값 panGyeolschDtBase를 schDtBase로 변경한다. */
	if(param.mobileSchDtBase) {
		param.schDtBase = param.mobileSchDtBase;
		delete param.mobileSchDtBase;
	}
	if(param.mobilePanGyeolschDtBase){
		param.schDtBase = param.mobilePanGyeolschDtBase;
		delete param.mobilePanGyeolschDtBase;
	}
	if(quickType =='beop'){
		param.ntstSysClCd = param.mobileNtstSysClCd;
		delete param.mobileNtstSysClCd;
		//ntstTextUqno = 0006 (Lpad, 4자리) + 10 (의~관련 2자리, 없으면 00) + 5(조)
		var ntstTextUqno = "";
		var ntstTextUqnoPrev = Util.lPad(param.remoteBeopPrevInput, 4);
		var ntstTextUqnoNext = Util.lPad(param.remoteBeopNextInput, 2);
		delete param.remoteBeopPrevInput;
		delete param.remoteBeopNextInput;
		if(ntstTextUqnoPrev+ntstTextUqnoNext != '000000'){
			param.ntstTextUqno = ntstTextUqnoPrev+ntstTextUqnoNext+'5';	
		}
		param.ntstTlawClCd = $("#mobileBeopTypeSelect :selected").attr('data-ntsttlawclcd');
	}else if(quickType =='pan_gyeol'){
		param.startDt = param.bltnStrtDt;  
		param.endDt = param.bltnEndDt
		delete param.bltnStrtDt;
		delete param.bltnEndDt;
	}else if(quickType =='seosick'){
		param.searchType = "frml";
		param.schVcb = param.remoteSchVcb;
		delete param.remoteSchVcb;
	}

	return param;
}

