			var d = data[actionId];
			var $targetSelect = $('[data-quick-find-select="beop"]');
			$targetSelect.each(function(){
				$(this).find("option").remove();
				for(var i in d){
					var $option = $('<option>').val(d[i].ntstBscId).text(d[i].ntstNm);
					$option.attr('data-ntstTlawClCd', d[i].ntstTlawClCd);
					$(this).append($option);
				}
			})

			if($(this).attr('data-remote-value') && $(this).find('option[value="'+$(this).attr('data-remote-value')+'"]').length > 0){
				$(this).val($(this).attr('data-remote-value')).prop("selected",true);
				$(this).removeAttr('data-remote-value');
			}
		})
	}

