	/*퀵메뉴조회*/
	Biz.makeBkmrList = function(type){
		var data = ClientStorage.get('ntlisBkmr');
		if(data){
			var $bkmrTarget = $('[data-remote-area="bkmr"]');
			$bkmrTarget.children().remove();
			var $bkmrUl = $("<ul>");
			for(key in data){
				var $bkmrLi = $("<li>")
				var $bkmrA = $("<a>").attr({
					'href' : data[key].scrnUrl,
					'title' : data[key].menuTtl
					}).text(data[key].menuTtl)
				var $bkmrBtn = $("<button>").addClass("r_task_quick").attr('data-menuId',data[key].menuId);
				$bkmrBtn.on("click", function(){
					$("#bkmrDiv").attr('currentDeleteIdx', $("#bkmrDiv li").index($(this).closest("li")));
					var _data = ClientStorage.get('ntlisBkmr');
					delete _data[$(this).attr('data-menuId')];
					ClientStorage.set('ntlisBkmr', _data);
					Page.alert("퀵메뉴 삭제가 완료되었습니다.", function(){
						setTimeout(function(){
							var deleteIdx = $("#bkmrDiv").attr('currentDeleteIdx');
							var focusTarget = "";
							if(typeof deleteIdx != 'number'){
								deleteIdx = 0;	
							}
							if($("#bkmrDiv").find("li").length == 0 ){
								focusTarget = $("#bkmrDiv").siblings(".task_item_title").find("button");
							}else{
								deleteIdx = deleteIdx - 1; 
								focusTarget = $("#bkmrDiv").find("li").eq(deleteIdx).find("button"); 
							}
							focusTarget.focus();
						}, 100);
					});
					Biz.checkBkmrYn();
					Biz.makeBkmrList("delete");
				})
				var $bkmrSpan = $("<span>").addClass("hide").text("삭제");
				$bkmrLi.append($bkmrA, $bkmrBtn.append($bkmrSpan));
				$bkmrUl.append($bkmrLi);
				}
			$bkmrTarget.each(function(){
				var $clonUl = $bkmrUl.clone(true); 
				$(this).append($clonUl);
			});
		};
	}		

	/* 퀵메뉴 버튼 EventListener */
	$("#cmBkmrBtn").on("click", function(){
		if(!$(this).attr('data-menuId')) {
			return;
		}
		if(!ClientStorage.get('ntlisBkmr')){
			ClientStorage.set('ntlisBkmr', {});
		}
		$(this).toggleClass("active");
		var bkmrSpantext = "퀵메뉴 삭제됨";
		if($(this).hasClass("active")){
			bkmrSpantext = "퀵메뉴 추가됨";
		}
		$(this).find("span").text(bkmrSpantext);
		var originData = ClientStorage.get('ntlisBkmr');
		var msg = "";
		var _menuId = $(this).attr('data-menuId'); 
		var _menuTtl = $(this).attr('data-menuTtl'); 
		var _scrnUrl = $(this).attr('data-scrnUrl'); 
		if(_menuId in originData){
			delete originData[_menuId];
			ClientStorage.set('ntlisBkmr', originData);
			msg = "퀵메뉴가 삭제되었습니다.";
		}else{
			var _newData = {};
			_newData[_menuId] = {"menuId" : _menuId, "menuTtl" : _menuTtl, "scrnUrl" : _scrnUrl, "lstAltDtm" : Util.getToday()};
			Object.assign(_newData, originData);
			ClientStorage.set('ntlisBkmr', _newData);
			msg = "퀵메뉴가 등록되었습니다.";
		}
		Page.alert(msg);
		Biz.makeBkmrList();
	});

