		var $sebeopArea = $("[data-quick-find-area=sebeop]");
		for(key in data){
			/* 일자 radio button checked */
			if(key == "schDtBase" && data[key] != ""){
				$sebeopArea.find('[name="schDtBase"]').each(function(){
				    if($(this).val() == "DCM_RGT_DTM") { 
				    	$(this).prop('checked', true)
				    }

				})
			}else if(key == "startDt"){
				Biz.sebeopCalendar.setValue(data[key])
			}else if(key == "endDt"){
				Biz.sebeopCalendar.setEndValue(data[key])
			}else {
				$sebeopArea.find('[name="'+key+'"]').val(data[key]);
			}
		}
	}

