	/* 빠른찾기 법령 setValue */
	Biz.setRemoteBeopValue = function(data, type){
		var $beopArea = $('[data-quick-find-area="beop"]');
		if(!data['ntstSysClCd']) { return false;}
		$beopArea.each(function(){
			/* mobileCheck */
			if($(this).closest(".quick_find_wrap").hasClass("mo")){
				$(this).find('[name="mobileNtstSysClCd"][value="'+data['ntstSysClCd']+'"]').click();
				if(type == 'beop3depth'){
					$(this).find("#mobileBeop3depthBtn").prop('checked', true);
					$("#mobileNewStttOpen").prop("disabled",true).click();
					$("#mobileNewStttOpen").parents(".quick_find_item").next().find("button").text("새창열림").attr("title","새창열림");
				}else if (data.newStttOpen) {
					$("#mobileNewStttOpen").prop('checked', true);
					$("#mobileNewStttOpen").parents(".quick_find_item").next().find("button").text("새창열림").attr("title","새창열림");
				}
				$(this).find("select").attr('data-remote-value', data['ntstBscId']);
			}else{
				$(this).find('[name="ntstSysClCd"][value="'+data['ntstSysClCd']+'"]').click();
				if(type == 'beop3depth'){
					$(this).find("#beop3depthBtn").prop('checked', true);
					$("#newStttOpen").prop("disabled",true).click();
					$("#newStttOpen").parents(".quick_find_item").next().find("button").text("새창열림").attr("title","새창열림");
				}else if (data.newStttOpen) {
					$("#newStttOpen").prop('checked', true);
					$("#newStttOpen").parents(".quick_find_item").next().find("button").text("새창열림").attr("title","새창열림");
				}
				$(this).find("select").attr('data-remote-value', data['ntstBscId']);
			}

			if(data['ntstTextUqno'] && data['ntstTextUqno'] != "0000005"){
				var prevVal = data['ntstTextUqno'].substr(0,4);
				if(prevVal != "0000"){
					$(this).find('[name="remoteBeopPrevInput"]').val(parseInt(prevVal));
				}
				var nextVal = data['ntstTextUqno'].substr(4,2);
				if(nextVal != "00"){
					$(this).find('[name="remoteBeopNextInput"]').val(parseInt(nextVal));
				}
			}
		})



	}

